"""自编课程题库。运行后写入 data/questions.json；不会触碰学习记录。"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
QUESTIONS = []


def add(chapter, topic, stem, options, answer, hint, explanation, misconception, level="基础"):
    QUESTIONS.append(dict(
        id=f"DS{len(QUESTIONS)+1:03d}", chapter=chapter, topic=topic,
        family=f"{chapter}/{topic}", difficulty=level, stem=stem,
        options=dict(zip("ABCD", options)), answer=answer, hint=hint,
        explanation=explanation, misconception=misconception,
        source="本项目自编教学题（待课程教师复核）",
    ))


